/* PROTOTYPE — guided tours that build the application plugin by plugin, from the legal minimum to the full product.
   Each step declares `add` (plugins installed at this step). The tour engine (core.js, build mode) installs everything
   added up to the current step, so "Précédent" really goes back to the smaller application. */
(function () {
  const APO = window.APO;

  /* ---------- officine presets ---------- */
  const lotOf = (st, pid) => { const lots = st.stock[pid] || []; const l = lots.filter((x) => !x.recalled && x.qty > 0).sort((a, b) => a.exp.localeCompare(b.exp))[0] || lots.find((x) => !x.recalled) || lots[0]; return l ? l.lot : ""; };
  const off = (ids, extra) => APO.set((s) => { const st = s.officine; return { officine: { ...st, basket: ids.map((pid) => ({ pid, qty: 1, lot: lotOf(st, pid) })), customer: null, rx: {}, fse: false, receipt: null, rxFor: null, pay: "cash", garde: { ...st.garde, on: false }, ...(extra ? extra(st) : {}) } }; });

  APO.tour.officine = [
    { kicker: "Le minimum", add: [], go: "home", title: "Le minimum légal : le noyau et le pack Maroc",
      text: "Aucun plugin optionnel n'est installé. Il reste ce que la loi impose et ce dont toute officine a besoin : comptoir, stock, achats, carnet, tiers payant et FSE, registres, prix réglementés, rappels de lots, fiscalité et conformité. Ces plugins sont épinglés : on ne peut pas les retirer." ,
      run: () => { APO.set({ offline: false }); off([]); } },
    { kicker: "Le minimum", add: [], go: "counter", title: "Un comptoir déjà conforme, sans rien installer",
      text: "Le pack Maroc protège chaque vente dès le premier jour : Rivotril (tableau B) est bloqué tant que l'ordonnance sur carnet à souches n'est pas saisie, et le lot de Smecta rappelé est écarté. Remarquez qu'aucun conseil n'apparaît pour les deux paracétamols : ce sera le travail d'un plugin.",
      try: "« Saisir l'ordonnance », puis encaisser.", run: () => off(["p10", "p7", "p1", "p2"], () => ({ customer: "c1" })) },
    { kicker: "Conseil au comptoir", add: ["dup-therapy", "generics"], go: "counter", before: ["Doliprane et Dafalgan passent ensemble sans aucun avertissement.", "Augmentin est vendu en princeps, sans proposition de générique.", "Le pharmacien doit penser seul à vérifier."], after: ["Une carte « Doublon : paracétamol » apparaît au comptoir.", "Une carte « Générique disponible » montre l'écart de prix et le reste à charge.", "« Substituer » remplace la ligne et l'inscrit au registre de substitution."], title: "+ Doublon thérapeutique et substitution générique",
      text: "Deux règles Apotheka s'ajoutent au comptoir. Le doublon de paracétamol est signalé, et Augmentin propose son générique avec l'écart de prix et le reste à charge du patient. Elles fonctionnent même sans internet.",
      try: "Cliquer « Substituer » sur la carte du générique.", run: () => off(["p1", "p2", "p3"], () => ({ customer: "c1" })) },
    { kicker: "Partenaire", add: ["interactions"], go: "counter", before: ["Sintrom et Aspégic peuvent être délivrés ensemble sans alerte.", "Aucune base d'interactions sourcée au comptoir."], after: ["Une carte « Interaction majeure : acénocoumarol + aspirine » s'affiche.", "Source citée (MedRef 2026.4), évaluée localement, sans donnée patient.", "La vente n'est jamais bloquée : le pharmacien décide."], title: "+ Interactions médicamenteuses (partenaire)",
      text: "Une base d'interactions sous licence, fournie par un partenaire. Elle tourne au Maroc, sans donnée patient ni accès réseau. Elle conseille, elle ne bloque jamais : la décision reste au pharmacien.",
      run: () => off(["p9", "p8"], () => ({ rx: { p9: { n: "ORD-5520", prescriber: "Dr. M. Fassi · INPE 20914" } } })) },
    { kicker: "Service", add: ["special-orders", "garde"], go: "counter", before: ["Spasfon en rupture : le client repart sans solution.", "La nuit, pas de majoration de garde ni de registre de garde."], after: ["Une carte propose une commande client avec acompte et SMS à l'arrivée.", "Un bouton Garde dans le ticket ajoute la majoration de nuit.", "Le registre de garde se remplit automatiquement."], title: "+ Commandes clients et mode garde",
      text: "Spasfon est en rupture : le comptoir propose une commande client avec acompte et SMS à l'arrivée. Le mode garde ajoute la majoration de nuit sur le ticket et ouvre le registre de garde.",
      run: () => off(["p13", "p14"], (st) => ({ garde: { ...st.garde, on: true } })) },
    { kicker: "Encaissement", add: ["tpe", "sms"], go: "counter", before: ["Le montant est retapé à la main sur le terminal de paiement.", "Les remises carte se rapprochent à la main en fin de journée.", "Aucun moyen de prévenir un patient que son produit est arrivé."], after: ["Le bouton « Carte · TPE » envoie le montant au terminal.", "Le rapprochement des remises carte est automatique à la clôture.", "Une commande ⌘K envoie les SMS « produit arrivé » (numéro et référence seulement)."], title: "+ Paiement carte (TPE) et SMS patients",
      text: "Le montant part directement au terminal de paiement et la remise est rapprochée en fin de journée. Les SMS ne contiennent qu'un numéro et une référence, jamais d'information de santé.",
      run: () => off(["p1", "p11"], () => ({ pay: "card" })) },
    { kicker: "Grossistes", add: ["wh.dawa", "wh.atlas", "wh.fallback"], go: "purchasing", before: ["Les commandes partent par téléphone ou par fax.", "Le bon de livraison est ressaisi ligne par ligne.", "Pas de suivi de la commande jusqu'à la livraison."], after: ["Dawa Maghreb et Grossiste Atlas reçoivent les commandes en direct.", "Le suivi s'affiche étape par étape jusqu'à la tournée.", "Le BL arrive prérempli : seuls les écarts sont à contrôler.", "Le grossiste sans API reçoit un bon de commande PDF par e-mail."], title: "+ Vos grossistes : Dawa Maghreb, Grossiste Atlas et ceux sans API",
      text: "Chaque grossiste publie sa propre connexion et apparaît sous son nom. Les commandes partent en direct, le suivi remonte en temps réel, et le bon de livraison arrive prérempli : vous ne contrôlez que les écarts. Le grossiste sans API reçoit un bon de commande par e-mail.", run: () => off([]) },
    { kicker: "Achats intelligents", add: ["smart-buy"], go: "smartbuy", before: ["Les quantités à commander se décident de mémoire.", "Pas de comparaison entre grossistes."], after: ["Un menu « Smart-buy » apparaît.", "Les quantités sont calculées sur vos ventes réelles.", "Chaque ligne compare prix, unités gratuites et délai, et choisit le meilleur coût net."], title: "+ Smart-buy",
      text: "Les quantités sont calculées sur vos ventes réelles, et chaque ligne compare prix, unités gratuites et délai entre vos grossistes. Chaque grossiste ne voit que sa propre commande." },
    { kicker: "Écosystème ouvert", add: ["wh.sud"], go: "smartbuy", before: ["Smart-buy compare vos grossistes actuels.", "Répartiteur Sud n'est pas connecté."], after: ["Une colonne « Répartiteur Sud » apparaît dans Smart-buy, marquée Nouveau.", "Ses prix et délais entrent dans la comparaison.", "Aucune mise à jour du logiciel n'a été nécessaire."], title: "+ Un nouveau grossiste rejoint Apotheka",
      text: "Répartiteur Sud vient de publier sa connexion. Une colonne de plus apparaît dans Smart-buy, sans mise à jour du logiciel et sans développement de notre côté." },
    { kicker: "Stock", add: ["expiry-radar"], go: "home", before: ["Les lots proches de la péremption se découvrent en rayon, trop tard.", "La fenêtre de retour au grossiste est souvent dépassée."], after: ["Une tuile « Péremptions à 3 mois » apparaît sur l'accueil.", "Chaque lot est lié à la date limite de retour chez son grossiste.", "Le retour se prépare en un clic dans Achats."], title: "+ Radar des péremptions",
      text: "Une tuile apparaît sur l'accueil : les lots qui périment dans 3 mois, liés à la fenêtre de retour du grossiste, avec un retour préparé en un clic." },
    { kicker: "Partenaire objets connectés", add: ["cold-chain"], go: "counter", before: ["La température des frigos se relève à la main sur un cahier.", "Rien au comptoir ne rappelle qu'un produit est froid."], after: ["Les sondes envoient leurs relevés en continu.", "Au comptoir, Lantus affiche la température du frigo et le conseil de transport.", "En cas d'excursion, une quarantaine est proposée au pharmacien."], title: "+ Chaîne du froid",
      text: "Les sondes des réfrigérateurs envoient leurs relevés. Au comptoir, Lantus affiche la température du frigo et rappelle la pochette isotherme. En cas d'excursion, une quarantaine est proposée, jamais imposée.",
      run: () => off(["p12"]) },
    { kicker: "Assistant", add: ["agent"], go: "agent", before: ["La commande de nuit et les relances de rejets CNSS se font à la main.", "Aucune explication des suggestions d'achat."], after: ["Un menu « Assistant » apparaît, avec des brouillons à valider.", "Chaque ligne se valide ou se rejette à la main.", "Aucune donnée patient n'est envoyée, et il ne touche jamais aux prix ni aux registres."], title: "+ L'assistant Apotheka",
      text: "Il prépare la commande de nuit, relance les rejets CNSS et explique ses suggestions. Il ne voit aucune donnée patient, ne touche ni aux prix ni aux registres, et chaque ligne se valide à la main." },
    { kicker: "Nouveaux métiers", add: ["preparations", "rental"], go: "doc:preparations", before: ["Les préparations se suivent sur papier.", "Les locations de fauteuils ou d'oxygène se notent dans un cahier."], after: ["Deux nouveaux menus : « Préparations » et « Location matériel ».", "Chaque document a son numéro, ses étapes et son historique.", "Ces écrans sont générés par Apotheka à partir de la déclaration du plugin."], title: "+ Préparations magistrales et location de matériel",
      text: "Ces plugins ajoutent des écrans entiers. Ils déclarent un type de document et Apotheka fournit la numérotation, les étapes, les droits et l'historique : l'écran est généré, pas développé." },
    { kicker: "Comptabilité et groupement", add: ["accounting", "groupement-sync"], go: "market", before: ["Le journal est ressaisi par la fiduciaire chaque mois.", "Les prix négociés du groupement se gèrent à part."], after: ["Une commande ⌘K exporte le journal vers Sage 100 Maroc.", "Le plugin privé du groupement synchronise prix et commandes groupées.", "Aucune donnée patient ne quitte la pharmacie."], title: "+ Export comptable et liaison avec votre groupement",
      text: "Le journal part chaque mois vers votre fiduciaire (Sage 100 Maroc). Un intégrateur a écrit un plugin privé pour le groupement Souss : prix négociés et commandes groupées, sans aucune donnée patient." },
    { kicker: "Changer de logiciel", add: ["import.winpharm", "import.sobrus"], go: "migration", before: ["Changer de logiciel veut dire tout ressaisir.", "Impossible d'essayer Apotheka sans arrêter l'ancien logiciel."], after: ["Un menu « Migration » importe produits, clients, carnet et historique.", "Le mode ombre fait tourner Apotheka à côté de l'ancien logiciel.", "Vous basculez le jour où vous êtes prêt."], title: "+ Migration depuis Winpharm ou Sobrus",
      text: "Produits, clients, carnet et historique sont importés. En mode ombre, Apotheka tourne à côté de votre logiciel actuel jusqu'au jour où vous basculez." },
    { kicker: "Thèmes", add: ["theme.majorelle"], go: "appearance", title: "L'apparence aussi est un plugin",
      before: ["Apparence de base : thème Apotheka Classique, vert officine, titres en Archivo.", "Le menu affiche le logo « A » et le nom Apotheka.", "Aucun thème partenaire installé."],
      after: ["Le bleu Majorelle et sa touche safran s'appliquent à tous les écrans, comptoir compris.", "Titres en Bricolage Grotesque, angles plus généreux.", "Le logo du menu passe au safran ; les couleurs d'alerte, les mentions légales et les prix ne bougent pas."],
      text: "Majorelle, du Studio Atlas, est un pack de données signé : couleurs, typographie et formes, sans une ligne de code. L'écran Apparence permet ensuite d'ajuster l'accent, les angles, la densité, le mode nuit et même le nom affiché, pour un groupement en marque blanche.",
      try: "Choisir « Sombre », ou taper « Souss Santé » dans Marque affichée." },
    { kicker: "Application complète", add: [], go: "home", title: "L'officine complète, construite plugin par plugin",
      text: "Partis du noyau et du pack Maroc, nous avons ajouté 22 plugins, thème compris, sans changer de logiciel ni perdre une donnée. Chacun peut être retiré à tout moment. WhatsApp reste en attente d'un avis juridique.",
      action: { label: "Comparer avec le noyau seul", run: () => APO.setBare(!APO.get().bare) }, run: () => off([]) },
  ];
  APO.tour.officine.build = true;

  /* ---------- parapharmacie presets ---------- */
  const L = (pid, vi, qty) => ({ key: pid + ":" + vi + ":s1", pid, vi, from: "s1", mode: "here", qty });
  const para = (lines, extra) => APO.set((s) => ({ para: { ...s.para, basket: lines, customer: null, picker: null, receipt: null, redeem: 0, ...(extra || {}) } }));

  APO.tour.para = [
    { kicker: "Le minimum", add: [], go: "home", title: "Le minimum : caisse, catalogue, stock et pack Maroc",
      text: "Aucun plugin optionnel. La parapharmacie a déjà sa caisse avec séries fiscales, son catalogue avec teintes et formats, son stock multi-boutiques, ses achats auprès des marques, et les règles marocaines : TVA, affichage des prix, interdictions cosmétiques.", run: () => { APO.set({ offline: false }); para([]); } },
    { kicker: "Le minimum", add: [], go: "pcounter", title: "Une caisse simple : le prix affiché, c'est le prix payé",
      text: "2 Anthelios et 3 Sensibio au prix catalogue. Pas de promotion, pas de fidélité : ce sont des plugins.", run: () => para([L("q1", 0, 2), L("q3", 0, 3)]) },
    { kicker: "Commerce", add: ["promo.engine"], go: "pcounter", before: ["2 Anthelios et 3 Sensibio au prix catalogue : 885,00 DH.", "Les promotions se calculent à la main, sans savoir qui les finance."], after: ["2ᵉ Anthelios à −50 % et Sensibio 3 pour 2 s'appliquent seuls : 626,50 DH.", "Chaque remise indique la part marque et la part boutique.", "Un menu « Promotions » apparaît."], title: "+ Moteur de promotions",
      text: "Les promotions s'appliquent toutes seules, même hors ligne : 2ᵉ Anthelios à −50 %, Sensibio 3 pour 2. Chaque remise indique qui la finance, la marque ou la boutique. Un menu Promotions apparaît.", run: () => para([L("q1", 0, 2), L("q3", 0, 3)]) },
    { kicker: "Commerce", add: ["loyalty"], go: "pcounter", before: ["Salma est une cliente anonyme à la caisse.", "Ses points et sa routine ne sont visibles nulle part."], after: ["Salma est reconnue : 1 240 points, profil de peau, routine.", "Une carte propose d'utiliser 500 points pour −50 DH.", "Un menu « Clientes & fidélité » apparaît."], title: "+ Fidélité, une carte pour toutes les boutiques",
      text: "Salma est reconnue : 1 240 points, profil de peau et routine. La carte propose d'utiliser ses points sur ce ticket. Le menu Clientes & fidélité apparaît.", try: "Cliquer « Utiliser 500 pts · −50 DH ».", run: () => para([L("q1", 0, 2), L("q3", 0, 3)], { customer: "k1" }) },
    { kicker: "Encaissement", add: ["tpe", "giftcards"], go: "pcounter", before: ["Montant retapé sur le terminal de paiement.", "Pas de cartes cadeaux valables dans toutes les boutiques."], after: ["Le paiement carte et QR wallet est relié à la caisse.", "Les cartes cadeaux s'émettent et s'utilisent dans les 4 boutiques.", "Paiement mixte : carte cadeau, carte bancaire et espèces."], title: "+ Paiement carte, wallets et cartes cadeaux",
      text: "Terminal de paiement, QR wallet et cartes cadeaux valables dans les 4 boutiques, avec paiement mixte.", run: () => para([L("q5", 0, 1), L("q8", 0, 1)], { customer: "k1" }) },
    { kicker: "Marques", add: ["promoters"], go: "pcounter", before: ["Les ventes des animatrices se comptent à la main.", "Les marques demandent des preuves difficiles à fournir."], after: ["Un sélecteur « Vendu par » apparaît sur le ticket.", "Hind est créditée des lignes La Roche-Posay.", "Un menu « Marques & animatrices » suit ventes et objectifs."], title: "+ Animatrices des marques",
      text: "Le ticket affiche « Vendu par » : Hind, l'animatrice La Roche-Posay pointée aujourd'hui, est créditée des lignes de sa marque. Ses ventes et son objectif apparaissent dans Marques & animatrices.", run: () => para([L("q1", 0, 2)], { customer: "k1" }) },
    { kicker: "Chaîne", add: ["chain.hq"], go: "hq", before: ["Chaque boutique change ses prix séparément.", "Les étiquettes à réimprimer ne sont pas suivies."], after: ["Un menu « Siège » apparaît.", "Un prix change à une date pour toutes les boutiques, avec exceptions.", "Alerte sous le plancher de marge et étiquettes à réimprimer par boutique."], title: "+ Siège de chaîne",
      text: "Le siège change un prix à une date donnée, autorise une exception pour Marrakech, est averti si la marge passe sous le plancher, et voit les étiquettes à réimprimer dans chaque boutique." },
    { kicker: "Stock", add: ["expiry.para"], go: "pstock", before: ["Les solaires périment en réserve sans être repérés.", "Les testeurs ouverts ne sont pas suivis."], after: ["Les lots à démarquer sont listés dans le stock.", "Démarque financée par la marque ou retour fournisseur proposé.", "Durée après ouverture des testeurs suivie."], title: "+ Fin de saison et péremption",
      text: "Les solaires qui périment avant l'été prochain sont repérés, avec une démarque financée par la marque ou un retour fournisseur. Les testeurs ouverts suivent leur durée après ouverture." },
    { kicker: "Canaux", add: ["social"], go: "inbox", before: ["Les messages des clientes se gèrent sur le téléphone de la boutique.", "Les commandes passées par message se perdent."], after: ["Un menu « Messages & commandes » regroupe WhatsApp et Instagram.", "Un message devient une réservation, un lien de paiement ou une commande.", "Seules les clientes qui ont donné leur accord reçoivent des offres."], title: "+ Vente sur WhatsApp et Instagram",
      text: "Une question sur une teinte devient une réservation en boutique, un lien de paiement ou une commande. Seules les clientes qui ont donné leur accord reçoivent des offres." },
    { kicker: "Canaux", add: ["ecom"], go: "channels", before: ["Le site et Jumia ont leur propre stock, avec des surventes.", "Les commandes en ligne sont ressaisies."], after: ["Un menu « E-commerce » apparaît.", "Le catalogue para est publié depuis le stock des boutiques.", "Un médicament ne peut jamais être publié."], title: "+ E-shop et Jumia sur le même stock",
      text: "Le catalogue para est publié depuis le même stock que les boutiques, sans double saisie ni survente. Un médicament ne peut jamais être publié : le noyau l'interdit." },
    { kicker: "Canaux", add: ["delivery"], go: "channels", before: ["Les livraisons s'organisent par téléphone avec le coursier.", "Le contre-remboursement se rapproche à la main."], after: ["Les commandes en ligne partent chez le coursier avec suivi.", "Le contre-remboursement est rapproché automatiquement.", "Parapharmacie uniquement."], title: "+ Livraison",
      text: "Les commandes en ligne partent chez le coursier avec contre-remboursement et suivi. Parapharmacie uniquement." },
    { kicker: "Partenaire", add: ["skin-diag"], go: "pcounter", before: ["La conseillère propose une routine de mémoire.", "Le profil de peau d'Imane n'est pas exploité."], after: ["Une carte du partenaire propose une routine pour peau sèche.", "« Ajouter » met le produit suggéré sur le ticket.", "Le profil reste au Maroc, avec le consentement de la cliente."], title: "+ Diagnostic de peau (partenaire)",
      text: "Imane a la peau sèche : la carte du partenaire propose une routine et ajoute le produit en un clic. Le profil reste au Maroc, avec son consentement.", run: () => para([L("q6", 0, 1)], { customer: "k2" }) },
    { kicker: "Marques", add: ["sellout", "lor.connect"], go: "promos", before: ["Les marques reçoivent des fichiers Excel par e-mail.", "Les promotions des marques sont ressaisies à la main."], after: ["Les ventes agrégées partent aux marques, jamais de données clientes.", "Le connecteur L'Oréal pousse une promotion signée, marquée Nouveau.", "La part de financement de la marque est prise en compte automatiquement."], title: "+ Sell-out et connecteur L'Oréal",
      text: "Les marques reçoivent des ventes agrégées, jamais de données clientes. Le connecteur L'Oréal pousse une promotion signée, avec sa part de financement : elle apparaît marquée Nouveau." },
    { kicker: "Assistant", add: ["agent"], go: "agent", before: ["Le réassort du week-end se prépare boutique par boutique.", "Transferts et commandes aux marques se décident à la main."], after: ["Un menu « Assistant » apparaît avec le plan de réassort.", "Chaque transfert et chaque commande se valident ligne par ligne.", "Il signale quand il a lu un texte tiers, comme des conditions commerciales."], title: "+ L'assistant Apotheka",
      text: "Il prépare le plan de réassort du week-end, transferts et commandes aux marques compris, et le soumet ligne par ligne. Il signale quand il a lu un texte tiers, comme des conditions commerciales." },
    { kicker: "Thèmes", add: ["theme.majorelle"], go: "appearance", title: "L'apparence aussi est un plugin",
      before: ["Apparence de base : thème Apotheka Classique, prune parapharmacie, titres en Archivo.", "Le menu affiche le logo « A » et le nom Apotheka.", "Aucun thème partenaire installé."],
      after: ["Le bleu Majorelle et sa touche safran s'appliquent à tous les écrans, caisse comprise.", "Titres en Bricolage Grotesque, angles plus généreux.", "Le logo du menu passe au safran ; les couleurs d'alerte, les mentions légales et les prix ne bougent pas."],
      text: "Majorelle, du Studio Atlas, est un pack de données signé : couleurs, typographie et formes, sans une ligne de code. L'écran Apparence permet ensuite d'ajuster l'accent, les angles, la densité, le mode nuit et même le nom affiché, pour une chaîne en marque blanche.",
      try: "Choisir « Sombre », ou taper « Paraphar Atlas » dans Marque affichée." },
    { kicker: "Application complète", add: [], go: "home", title: "La parapharmacie complète, construite plugin par plugin",
      text: "Partis de la caisse et du pack Maroc, nous avons ajouté 15 plugins, thème compris, sans changer de logiciel. Chacun se retire à tout moment, et ses données restent consultables.",
      action: { label: "Comparer avec le noyau seul", run: () => APO.setBare(!APO.get().bare) }, run: () => para([]) },
  ];
  APO.tour.para.build = true;
})();
